#!/usr/bin/env python3
"""Write docs/DECOMP.md: decompilation progress per version.

    python tools/decomp_progress.py s1 [s4 ...]

Counts functions in the static map, lists the hand-written routines from
c/hand/<ver>/hand.txt with their compare spec and whether the port runs
them (an hle_func HleHand_* in port/recomp*/bank*.cfg), and the source file
each lives in.
"""
import glob
import json
import os
import re
import sys


def main():
    vers = sys.argv[1:] or ['s1']
    out = ['# Decompilation progress', '',
           'Generated by `tools/decomp_progress.py`. A routine is *hand-written* when',
           'readable C in `c/hand/<ver>/` replaces the mechanically lifted version and',
           'passes `tools/difftest816.py` on everything its callers can observe',
           '(WRAM, hardware writes, S/D/DB and the live-out registers from',
           '`tools/liveout.py`). *In port* means the native port runs it through',
           '`port/src/r816_bridge.c`.', '']
    bridged = set()
    for cfg in glob.glob('port/recomp*/bank*.cfg'):
        for line in open(cfg):
            m = re.match(r'hle_func\s+([0-9A-Fa-f]+)\s+HleHand_(\w+)', line)
            if m:
                bridged.add(m.group(2))
    for ver in vers:
        code = json.load(open('build/%s/code.json' % ver))
        nfunc = len(code['funcs'])
        rows = []
        hp = 'c/hand/%s/hand.txt' % ver
        files = {}
        for f in glob.glob('c/hand/%s/*.c' % ver):
            for m in re.finditer(r'^void (\w+)_m\dx\d\(void\)', open(f).read(), re.M):
                files[m.group(1)] = os.path.basename(f)
        if os.path.exists(hp):
            for line in open(hp):
                t = line.split('#')[0].split()
                if len(t) >= 5:
                    rows.append((t[0], t[4], t[3], files.get(t[4], '?'), 'yes' if t[4] in bridged else ''))
        out.append('## %s' % ver)
        out.append('')
        out.append('%d functions in the static map; %d hand-written (%.1f%%), %d of them in the port.' % (
            nfunc, len(rows), 100.0 * len(rows) / max(1, nfunc), sum(1 for r in rows if r[4])))
        out.append('')
        out.append('| Address | Routine | Compare | File | In port |')
        out.append('|---|---|---|---|---|')
        for addr, name, spec, f, inport in sorted(rows):
            out.append('| `$%s:%s` | %s | `%s` | `%s` | %s |' % (addr[:2], addr[2:], name, spec, f, inport))
        out.append('')
    open('docs/DECOMP.md', 'w', encoding='utf-8', newline='\n').write('\n'.join(out) + '\n')
    print('wrote docs/DECOMP.md')


if __name__ == '__main__':
    main()
